/* Numera Academy — Páginas Revisão e Progresso (conquistas, camarim e backup).
   Parte da interface (antes, app.js). Os arquivos de js/site e js/paginas são scripts clássicos que
   compartilham as mesmas variáveis; a ordem de carregamento está no index.html. */
'use strict';
/* ---------- Revisão e progresso ---------- */
function review(){const all=Object.keys(p.review),ready=due(),trs=TR?TR.reviewSection():'';if(s.reviewId&&P.ids.has(s.reviewId))return `<div class="player">${playerTop(['current'],'Revisão ativa','review-close','')}<div class="player-body"><div class="player-col"><span class="eyebrow">Revisão ativa</span><p class="coach">Tente lembrar o procedimento antes de abrir a dica. Um acerto sem ajuda adia a próxima revisão.</p>${question(taskFor(s.reviewId),s.reviewId,'review-next')}</div></div></div>`;
 return `<div class="wrap page-body">${heading('Revisão','Erros que viram aprendizado','As questões com dificuldade e os diagnósticos errados do Treino ficam aqui. Depois de revisões sem ajuda, o intervalo cresce de 1 para 3, 7 e 14 dias.')}${trs}${all.length?`<div class="stat-row"><div class="stat card"><span>Para revisar hoje</span><b>${ready.length}</b></div><div class="stat card"><span>No seu caderno</span><b>${all.length}</b></div><div class="stat card action"><span>Seu próximo passo</span>${btn('Revisar uma questão '+icon('arrow'),'review-start','primary',`data-id="${ready[0]||all[0]}"`)}</div></div><div class="review-list">${all.map(id=>`<article class="card review-row"><span class="review-marker ${p.review[id].due<=P.day()?'due':''}" aria-hidden="true">${p.review[id].due<=P.day()?'↻':'✓'}</span><div><span class="eyebrow">${p.review[id].due<=P.day()?'Revisão disponível':'Próxima revisão: '+p.review[id].due.split('-').reverse().join('/')}</span><h3>${safe(taskFor(id).q.replace('DESAFIO FINAL: ',''))}</h3></div>${btn('Praticar','review-start','ghost',`data-id="${id}"`)}</article>`).join('')}</div>`:trs?'':`<section class="card empty-state">${icon('review')}<h2 class="display">Seu caderno ainda está em branco</h2><p>Quando uma questão exigir outra tentativa ou uma dica, ela aparece aqui.</p>${btn('Começar uma trilha','nav','primary','data-page="academy"')}</section>`}</div>`;}
const badgeList=()=>[
['Primeira descoberta','Conclua uma atividade.',totalDone()>=1,'✦'],['Trilha completa','Conclua as 12 etapas de um método.',C.METHODS.some(m=>doneCount(m.id)===12),'◇'],['Modelador','Conclua uma missão de 3 etapas.',C.CASES.some(c=>c.tasks.every((_,i)=>p.completed[`p:${c.id}:${i}`])),'◈'],['Explorador do terminal','Resolva uma equação ou sistema.',p.labCount>0,'λ'],['Constância','Pratique em 3 dias consecutivos.',P.streak(p)>=3,'↗'],['Mente numérica',`Conclua as ${C.METHODS.length*12} etapas de estudo.`,courseDone()===C.METHODS.length*12,'Σ'],['Caçador de Raízes','Vença uma fase na Calculândia.',(calcSummary()||{wins:0}).wins>=1,'▲'],['Turma reunida','Jogue uma partida completa de Quem Divergiu?',qdSummary().games>=1,'ε'],['Autonomia','Conquiste 3 estrelas em 10 atividades.',Object.values(p.completed).filter(c=>c.stars===3).length>=10,'★'],['Combo','Acerte 3 desafios seguidos.',(p.best||0)>=3,'⚡'],['Desbravador','Complete 3 mundos da jornada.',C.METHODS.filter(m=>doneCount(m.id)===12).length>=3,'⛰'],['Estilo próprio','Compre uma roupa para Raiz e Pivô no camarim.',(p.owned||[]).length>0,'✿']];
function confirmBox(){if(s.confirm==='reset')return `<div class="confirm card" role="alertdialog" aria-labelledby="confirm-title"><h3 id="confirm-title">Apagar todo o progresso local?</h3><p>Exporte um backup antes, se quiser guardá-lo. Essa ação não pode ser desfeita.</p><div class="row-actions">${btn('Apagar progresso','confirm-yes','danger')}${btn('Cancelar','confirm-no','ghost')}</div></div>`;if(s.confirm==='restore'&&s.pendingRestore)return `<div class="confirm card" role="alertdialog" aria-labelledby="confirm-title"><h3 id="confirm-title">Substituir o progresso atual pelo backup?</h3><p>Trilhas: ${Object.keys(s.pendingRestore.trilhas.completed||{}).length} atividades concluídas e ${s.pendingRestore.trilhas.xp??0} XP.${s.pendingRestore.full&&TR?(()=>{const d=TR.describe(s.pendingRestore.treino);return ` Treino: ${d.exercises} exercícios com progresso e ${d.provas} ${d.provas===1?'prova':'provas'} no histórico.`;})():' Este arquivo é de uma versão anterior e só traz as trilhas; o Treino atual fica como está.'}</p><div class="row-actions">${btn('Substituir progresso','confirm-yes','primary')}${btn('Cancelar','confirm-no','ghost')}</div></div>`;return '';}
// Camarim (v11): o que as moedas compram. Só enfeite: nenhuma roupa muda a dificuldade ou a nota.
function camarim(){const MZ=window.NumeraMascotes;if(!MZ)return '';const on=p.outfit||[],owned=p.owned||[],coins=p.coins||0;
 return `<section class="card camarim" aria-labelledby="cam-t"><div class="cam-stage">${MZ.svg(on,'cam')}</div><div class="cam-body"><span class="eyebrow">Camarim</span><h2 id="cam-t">Raiz e Pivô</h2><p>A Raiz é um rabanete: a raiz que a gente procura em toda equação. O Pivô é um bloquinho de matriz de luvas de boxe, o pivô da Eliminação de Gauss, que gira quando dança. Os dois torcem por você nos desafios e, a cada 3 acertos seguidos, o Pivô soca a caixa Σ e caem moedas. Troque as moedas por roupas para o casal.</p>
 <div class="cam-items">${MZ.ITEMS.map(it=>{const has=owned.includes(it.id),worn=on.includes(it.id);return `<div class="cam-item ${worn?'worn':''}"><b>${it.name}</b><small>${it.who==='raiz'?'para a Raiz':'para o Pivô'}</small>${has?btn(worn?'Tirar':'Vestir','equip',worn?'ghost':'blue',`data-id="${it.id}" aria-pressed="${worn}"`):btn(`<span class="coin-ico" aria-hidden="true">√</span> ${it.price}`,'buy',coins>=it.price?'primary':'ghost',`data-id="${it.id}" aria-label="Comprar ${it.name} por ${it.price} moedas" ${coins>=it.price?'':'disabled'}`)}</div>`;}).join('')}</div>
 <p class="fine">Moedas: +2 por etapa nova, +5 por etapa de missão, +5 a cada 3 acertos seguidos (com pelo menos uma atividade nova no meio), +10 por nível e +30 por mundo completo.</p></div></section>`;}
function progress(){const three=Object.values(p.completed).filter(v=>v.stars===3).length,badges=badgeList();return `<div class="wrap page-body">${heading('Progresso','Cada conquista tem uma história','Conclusão mede as atividades feitas. Estrelas registram sua melhor tentativa e não são uma certificação de domínio.')}
 <div class="stat-row"><div class="stat card"><span>Experiência · nível ${level()}</span><b>${p.xp}<small> XP</small></b>${bar(p.xp%200,200,'Progresso até o próximo nível')}</div><div class="stat card"><span>Atividades concluídas</span><b>${totalDone()}<small>/${visibleIds().length}</small></b></div><div class="stat card"><span>Com 3 estrelas</span><b>${three}</b></div><div class="stat card"><span>Moedas · melhor sequência: ${p.best||0}</span><b>${p.coins||0}</b></div></div>
 ${camarim()}
 ${treinoCard()}
 <div class="two-col"><section class="card"><h2>Seu mapa de aprendizado</h2>${C.METHODS.map(m=>`<div class="method-progress"><span class="symbol small tone-${m.id}" aria-hidden="true">${safe(m.symbol)}</span><div><div class="mp-row"><span>${m.title}</span><b>${doneCount(m.id)}/12</b></div>${bar(doneCount(m.id),12,'Progresso em '+m.title)}</div></div>`).join('')}</section><section class="card"><h2>Últimos 14 dias</h2><p>Atividades diferentes concluídas em cada dia.</p><div class="calendar">${Array.from({length:14},(_,i)=>{const d=new Date();d.setDate(d.getDate()-13+i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,n=p.activity[key]?.length||0;return `<div class="day ${n?'done':''} ${n>=3?'goal':''}" title="${key}: ${n} atividades"><span>${d.getDate()}</span><b>${n||'·'}</b></div>`;}).join('')}</div><div class="callout"><b>${P.streak(p)} ${P.streak(p)===1?'dia':'dias'} de sequência</b><p>Conta dias consecutivos com atividades concluídas, terminando hoje ou ontem.</p></div></section></div>
 <div class="section-head row tight"><h2>Conquistas</h2>${tag(`${badges.filter(b=>b[2]).length} de ${badges.length} desbloqueadas`)}</div><div class="badge-grid">${badges.map(([t,d,yes,mark])=>`<article class="card badge ${yes?'earned':'locked'}"><span class="badge-mark" aria-hidden="true">${mark}</span><h3>${t}</h3><p>${d}</p><small>${yes?'Desbloqueada ✓':'Em construção'}</small></article>`).join('')}</div>
 <section class="card backup"><div><h3>Leve seu progresso com você</h3><p>O backup é um único arquivo com tudo: trilhas, XP, Treino, provas, revisões e o que você já leu. Importe em outro navegador. Os dados ficam neste dispositivo.</p></div><div class="row-actions">${btn('Exportar backup','backup','ghost')}<label class="btn ghost" for="restore">Importar backup</label><input class="sr-only" type="file" id="restore" accept="application/json,.json">${btn('Reiniciar progresso','reset','danger-ghost')}</div></section>${confirmBox()}</div>`;}

